=== FILE: sync_fifo.v ===
// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Interface: interface_spec.md. Implementation plan: microarchitecture.md.
//  - Occupancy is an explicit count register (works for any DEPTH >= 2).
//  - Pointers wrap by comparing with DEPTH-1, never by binary overflow.
//  - A write is accepted when !full, a read when !empty (state before the edge).
//  - rd_data is a combinational read of the oldest slot (undefined when empty).
//  - rst_n is synchronous, active low; it clears pointers and count, not storage.
module sync_fifo #(
  parameter integer DEPTH = 8,
  parameter integer WIDTH = 8
) (
  input  wire                       clk,
  input  wire                       rst_n,
  input  wire                       wr_en,
  input  wire [WIDTH-1:0]           wr_data,
  output wire                       full,
  input  wire                       rd_en,
  output wire [WIDTH-1:0]           rd_data,
  output wire                       empty,
  output wire [$clog2(DEPTH+1)-1:0] count
);

  localparam integer AW     = $clog2(DEPTH);
  localparam integer CW     = $clog2(DEPTH+1);
  localparam integer LAST_I = DEPTH - 1;
  localparam integer ONE_I  = 1;

  localparam [AW-1:0] PTR_ZERO = {AW{1'b0}};
  localparam [AW-1:0] PTR_ONE  = ONE_I[AW-1:0];
  localparam [AW-1:0] PTR_LAST = LAST_I[AW-1:0];
  localparam [CW-1:0] CNT_ZERO = {CW{1'b0}};
  localparam [CW-1:0] CNT_ONE  = ONE_I[CW-1:0];
  localparam [CW-1:0] CNT_FULL = DEPTH[CW-1:0];

  // Storage: datapath, not reset.
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  reg [AW-1:0] wr_ptr_q;
  reg [AW-1:0] wr_ptr_d;
  reg [AW-1:0] rd_ptr_q;
  reg [AW-1:0] rd_ptr_d;
  reg [CW-1:0] count_q;
  reg [CW-1:0] count_d;

  wire wr_acc;
  wire rd_acc;

  assign full    = (count_q == CNT_FULL);
  assign empty   = (count_q == CNT_ZERO);
  assign count   = count_q;
  assign wr_acc  = wr_en && !full;
  assign rd_acc  = rd_en && !empty;
  assign rd_data = mem[rd_ptr_q];

  // Next-state logic: every variable has a default, so no latch.
  always @* begin
    wr_ptr_d = wr_ptr_q;
    rd_ptr_d = rd_ptr_q;
    count_d  = count_q;

    if (wr_acc) begin
      if (wr_ptr_q == PTR_LAST) begin
        wr_ptr_d = PTR_ZERO;
      end else begin
        wr_ptr_d = wr_ptr_q + PTR_ONE;
      end
    end

    if (rd_acc) begin
      if (rd_ptr_q == PTR_LAST) begin
        rd_ptr_d = PTR_ZERO;
      end else begin
        rd_ptr_d = rd_ptr_q + PTR_ONE;
      end
    end

    if (wr_acc && !rd_acc) begin
      count_d = count_q + CNT_ONE;
    end else if (rd_acc && !wr_acc) begin
      count_d = count_q - CNT_ONE;
    end
  end

  // Control registers: synchronous active-low reset.
  always @(posedge clk) begin
    if (!rst_n) begin
      wr_ptr_q <= PTR_ZERO;
      rd_ptr_q <= PTR_ZERO;
      count_q  <= CNT_ZERO;
    end else begin
      wr_ptr_q <= wr_ptr_d;
      rd_ptr_q <= rd_ptr_d;
      count_q  <= count_d;
    end
  end

  // Storage write: only outside reset, only on an accepted write.
  always @(posedge clk) begin
    if (rst_n && wr_acc) begin
      mem[wr_ptr_q] <= wr_data;
    end
  end

`ifdef FORMAL
  // Design-intent properties. Not yet backed by a SymbiYosys job.
  reg f_past_valid = 1'b0;

  always @(posedge clk) begin
    f_past_valid <= 1'b1;
  end

  always @(*) begin
    if (!f_past_valid) begin
      assume(!rst_n);
    end
  end

  always @(*) begin
    if (f_past_valid) begin
      assert(!(full && empty));
      assert(count_q <= CNT_FULL);
      assert(wr_ptr_q <= PTR_LAST);
      assert(rd_ptr_q <= PTR_LAST);
      assert(((rd_ptr_q + count_q) % DEPTH) == wr_ptr_q);
    end
  end

  always @(posedge clk) begin
    if (f_past_valid) begin
      if (!$past(rst_n)) begin
        assert(count_q == CNT_ZERO);
        assert(wr_ptr_q == PTR_ZERO);
        assert(rd_ptr_q == PTR_ZERO);
      end else begin
        if ($past(wr_acc) && !$past(rd_acc)) begin
          assert(count_q == $past(count_q) + CNT_ONE);
        end
        if ($past(rd_acc) && !$past(wr_acc)) begin
          assert(count_q == $past(count_q) - CNT_ONE);
        end
        if ($past(wr_acc) == $past(rd_acc)) begin
          assert(count_q == $past(count_q));
        end
        if (!$past(wr_acc)) begin
          assert(wr_ptr_q == $past(wr_ptr_q));
        end
        if (!$past(rd_acc)) begin
          assert(rd_ptr_q == $past(rd_ptr_q));
        end
      end
    end
  end

  always @(posedge clk) begin
    if (f_past_valid && rst_n) begin
      cover(full);
    end
  end
`endif

endmodule
=== END FILE ===
