// Self-checking testbench for sync_fifo.
// Three lanes share one stimulus: DEPTH 8/WIDTH 8, DEPTH 5/WIDTH 12, DEPTH 2/WIDTH 1.
// Each lane checks count, full, empty and rd_data against a reference queue
// before every rising edge, and counts coverage goals that must all be hit.

module sync_fifo_tb_lane #(
  parameter integer DEPTH = 8,
  parameter integer WIDTH = 8,
  parameter integer LANE  = 0
) (
  input  wire             clk,
  input  wire             rst_n,
  input  wire             wr_en,
  input  wire             rd_en,
  input  wire [WIDTH-1:0] wr_data,
  input  wire             final_chk,
  output wire [31:0]      n_pass,
  output wire [31:0]      n_fail
);

  localparam integer CW = $clog2(DEPTH+1);
  localparam integer QW = WIDTH * DEPTH;

  wire             full;
  wire             empty;
  wire [WIDTH-1:0] rd_data;
  wire [CW-1:0]    count;

  sync_fifo #(.DEPTH(DEPTH), .WIDTH(WIDTH)) dut (
    .clk     (clk),
    .rst_n   (rst_n),
    .wr_en   (wr_en),
    .wr_data (wr_data),
    .full    (full),
    .rd_en   (rd_en),
    .rd_data (rd_data),
    .empty   (empty),
    .count   (count)
  );

  wire [31:0] count32 = {{(32-CW){1'b0}}, count};

  // Reference queue: oldest entry in bits [WIDTH-1:0]; bits past m_cnt are zero.
  reg [QW-1:0] qv       = {QW{1'b0}};
  reg [31:0]   m_cnt    = 32'd0;
  reg          m_valid  = 1'b0;
  reg          m_full   = 1'b0;
  reg          m_empty  = 1'b1;
  reg          m_wr     = 1'b0;
  reg          m_rd     = 1'b0;
  reg          seen_full = 1'b0;
  reg [31:0]   rd_since = 32'd0;

  reg [31:0] pass_r = 32'd0;
  reg [31:0] fail_r = 32'd0;

  reg [31:0] c_full        = 32'd0;
  reg [31:0] c_wr_full     = 32'd0;
  reg [31:0] c_drain       = 32'd0;
  reg [31:0] c_rd_empty    = 32'd0;
  reg [31:0] c_both_empty  = 32'd0;
  reg [31:0] c_both_full   = 32'd0;
  reg [31:0] c_both_mid    = 32'd0;
  reg [31:0] c_wrap        = 32'd0;
  reg [31:0] c_rst_traffic = 32'd0;
  reg        final_done    = 1'b0;

  assign n_pass = pass_r;
  assign n_fail = fail_r;

  always @(posedge clk) begin
    // 1. Check the state after the last edge (outputs sampled before this edge updates them).
    if (m_valid) begin
      m_full  = (m_cnt == DEPTH);
      m_empty = (m_cnt == 32'd0);

      if (count32 == m_cnt) pass_r = pass_r + 32'd1;
      else begin
        fail_r = fail_r + 32'd1;
        $error("lane %0d (DEPTH %0d) t=%0t: count %0d, expected %0d", LANE, DEPTH, $time, count32, m_cnt);
      end

      if (full == m_full) pass_r = pass_r + 32'd1;
      else begin
        fail_r = fail_r + 32'd1;
        $error("lane %0d (DEPTH %0d) t=%0t: full %0d, expected %0d", LANE, DEPTH, $time, full, m_full);
      end

      if (empty == m_empty) pass_r = pass_r + 32'd1;
      else begin
        fail_r = fail_r + 32'd1;
        $error("lane %0d (DEPTH %0d) t=%0t: empty %0d, expected %0d", LANE, DEPTH, $time, empty, m_empty);
      end

      if (!(full && empty)) pass_r = pass_r + 32'd1;
      else begin
        fail_r = fail_r + 32'd1;
        $error("lane %0d (DEPTH %0d) t=%0t: full and empty both high", LANE, DEPTH, $time);
      end

      if (!m_empty) begin
        if (rd_data == qv[WIDTH-1:0]) pass_r = pass_r + 32'd1;
        else begin
          fail_r = fail_r + 32'd1;
          $error("lane %0d (DEPTH %0d) t=%0t: rd_data %h, expected %h", LANE, DEPTH, $time, rd_data, qv[WIDTH-1:0]);
        end
      end

      // Coverage of the interface spec's corner cases.
      if (rst_n) begin
        if (m_full) begin
          c_full    = c_full + 32'd1;
          seen_full = 1'b1;
        end
        if (m_empty && seen_full) begin
          c_drain   = c_drain + 32'd1;
          seen_full = 1'b0;
        end
        if (wr_en && m_full)                         c_wr_full    = c_wr_full + 32'd1;
        if (rd_en && m_empty)                        c_rd_empty   = c_rd_empty + 32'd1;
        if (wr_en && rd_en && m_empty)               c_both_empty = c_both_empty + 32'd1;
        if (wr_en && rd_en && m_full)                c_both_full  = c_both_full + 32'd1;
        if (wr_en && rd_en && !m_full && !m_empty)   c_both_mid   = c_both_mid + 32'd1;
      end else if (!m_empty) begin
        c_rst_traffic = c_rst_traffic + 32'd1;
      end
    end

    // 2. Advance the reference model with the inputs sampled at this edge.
    if (!rst_n) begin
      qv        = {QW{1'b0}};
      m_cnt     = 32'd0;
      rd_since  = 32'd0;
      seen_full = 1'b0;
      m_valid   = 1'b1;
    end else if (m_valid) begin
      m_wr = wr_en && (m_cnt != DEPTH);
      m_rd = rd_en && (m_cnt != 32'd0);
      if (m_rd) begin
        qv       = qv >> WIDTH;
        m_cnt    = m_cnt - 32'd1;
        rd_since = rd_since + 32'd1;
        if (rd_since > DEPTH) c_wrap = c_wrap + 32'd1;
      end
      if (m_wr) begin
        qv    = qv | ({{(QW-WIDTH){1'b0}}, wr_data} << (WIDTH * m_cnt));
        m_cnt = m_cnt + 32'd1;
      end
    end

    // 3. Coverage verdict, once, at the end of the run.
    if (final_chk && !final_done) begin
      final_done = 1'b1;
      if (c_full        != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'filled to full' not reached", LANE, DEPTH); end
      if (c_wr_full     != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'write while full' not reached", LANE, DEPTH); end
      if (c_drain       != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'drained to empty' not reached", LANE, DEPTH); end
      if (c_rd_empty    != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'read while empty' not reached", LANE, DEPTH); end
      if (c_both_empty  != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'write and read when empty' not reached", LANE, DEPTH); end
      if (c_both_full   != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'write and read when full' not reached", LANE, DEPTH); end
      if (c_both_mid    != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'write and read in between' not reached", LANE, DEPTH); end
      if (c_wrap        != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'pointer wrap-around' not reached", LANE, DEPTH); end
      if (c_rst_traffic != 32'd0) pass_r = pass_r + 32'd1; else begin fail_r = fail_r + 32'd1; $error("lane %0d (DEPTH %0d): goal 'reset during traffic' not reached", LANE, DEPTH); end
    end
  end

endmodule

module sync_fifo_tb;

  reg         clk       = 1'b0;
  reg         rst_n     = 1'b0;
  reg         wr_en     = 1'b1;
  reg         rd_en     = 1'b1;
  reg [11:0]  wr_data   = 12'd0;
  reg [11:0]  dctr      = 12'h0A5;
  reg         final_chk = 1'b0;
  reg [31:0]  r         = 32'd0;
  reg [8*64-1:0] nonce  = {(8*64){1'b0}};
  reg [31:0]  passed    = 32'd0;
  reg [31:0]  failed    = 32'd0;
  integer     i;
  integer     phase;

  wire [31:0] pass_a;
  wire [31:0] fail_a;
  wire [31:0] pass_b;
  wire [31:0] fail_b;
  wire [31:0] pass_c;
  wire [31:0] fail_c;

  always #5 clk = ~clk;

  sync_fifo_tb_lane #(.DEPTH(8), .WIDTH(8), .LANE(0)) lane_a (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
    .wr_data(wr_data[7:0]), .final_chk(final_chk),
    .n_pass(pass_a), .n_fail(fail_a)
  );

  sync_fifo_tb_lane #(.DEPTH(5), .WIDTH(12), .LANE(1)) lane_b (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
    .wr_data(wr_data), .final_chk(final_chk),
    .n_pass(pass_b), .n_fail(fail_b)
  );

  sync_fifo_tb_lane #(.DEPTH(2), .WIDTH(1), .LANE(2)) lane_c (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .rd_en(rd_en),
    .wr_data(wr_data[0:0]), .final_chk(final_chk),
    .n_pass(pass_c), .n_fail(fail_c)
  );

  // One cycle of stimulus, applied at the falling edge.
  task cyc;
    input rst;
    input w;
    input rd;
    begin
      @(negedge clk);
      rst_n   = rst;
      wr_en   = w;
      rd_en   = rd;
      wr_data = dctr;
      dctr    = dctr + 12'd37;
    end
  endtask

  initial begin
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};

    // Reset with both requests held high: they must be ignored.
    cyc(1'b0, 1'b1, 1'b1);
    cyc(1'b0, 1'b1, 1'b1);

    // Read while empty, then write and read together when empty.
    cyc(1'b1, 1'b0, 1'b1);
    cyc(1'b1, 1'b1, 1'b1);
    cyc(1'b1, 1'b0, 1'b0);

    // Fill past full: the extra writes must be dropped.
    for (i = 0; i < 10; i = i + 1) cyc(1'b1, 1'b1, 1'b0);

    // Write and read together when full.
    cyc(1'b1, 1'b1, 1'b1);
    cyc(1'b1, 1'b1, 1'b1);
    cyc(1'b1, 1'b1, 1'b1);
    cyc(1'b1, 1'b0, 1'b0);

    // Drain past empty: the extra reads must be ignored.
    for (i = 0; i < 10; i = i + 1) cyc(1'b1, 1'b0, 1'b1);

    // Write and read together in between (one entry held).
    cyc(1'b1, 1'b1, 1'b0);
    for (i = 0; i < 4; i = i + 1) cyc(1'b1, 1'b1, 1'b1);
    cyc(1'b1, 1'b0, 1'b0);

    // Reset during traffic.
    cyc(1'b1, 1'b1, 1'b0);
    cyc(1'b0, 1'b1, 1'b0);
    cyc(1'b0, 1'b0, 1'b0);
    cyc(1'b1, 1'b0, 1'b1);

    // Random traffic: fill-biased, drain-biased and balanced phases, with rare resets.
    for (phase = 0; phase < 6; phase = phase + 1) begin
      for (i = 0; i < 200; i = i + 1) begin
        r = $random;
        case (phase % 3)
          0:       cyc(r[15:8] != 8'd0, r[2:0] != 3'd0, r[5:3] == 3'd0);
          1:       cyc(r[15:8] != 8'd0, r[2:0] == 3'd0, r[5:3] != 3'd0);
          default: cyc(r[15:8] != 8'd0, r[0], r[1]);
        endcase
      end
    end

    // Idle, then ask every lane for its coverage verdict.
    cyc(1'b1, 1'b0, 1'b0);
    cyc(1'b1, 1'b0, 1'b0);
    @(negedge clk);
    final_chk = 1'b1;
    @(negedge clk);
    final_chk = 1'b0;
    @(negedge clk);

    passed = pass_a + pass_b + pass_c;
    failed = fail_a + fail_b + fail_c;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
=== END FILE ===
